<section class="panel"><div class="panel-heading"><div><h2>Ventas por cliente</h2><p>Precios históricos × cantidades × (1 − descuento). No incluye flete ni impuestos.</p></div><a class="btn btn-outline-primary" href="<?= e(url('reports-export',array_intersect_key($_GET,array_flip(['from','to'])))) ?>">↓ Exportar CSV</a></div><form class="filter-bar" method="get"><input type="hidden" name="r" value="reports"><?php foreach(['from'=>'Desde','to'=>'Hasta'] as $k=>$label): ?><div><label class="form-label" for="<?= $k ?>"><?= $label ?></label><input type="date" class="form-control" id="<?= $k ?>" name="<?= $k ?>" value="<?= e($_GET[$k]??'') ?>"></div><?php endforeach ?><button class="btn btn-primary align-self-end">Actualizar</button><a class="btn btn-light align-self-end" href="<?= e(url('reports')) ?>">Todo el histórico</a></form><div class="report-summary"><span>Venta neta del período<strong><?= money(array_sum(array_column($rows,'Sales'))) ?></strong></span><span>Clientes con ventas<strong><?= count($rows) ?></strong></span><span>Pedidos<strong><?= array_sum(array_column($rows,'OrdersCount')) ?></strong></span></div><div class="table-responsive"><table class="table"><thead><tr><th>Código</th><th>Empresa</th><th>País</th><th>Pedidos</th><th>Venta neta USD</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($r as $key=>$v): ?><td><?= $key==='Sales'?money($v):e($v) ?></td><?php endforeach ?></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="empty-state">Sin ventas en el período seleccionado.</td></tr><?php endif ?></tbody></table></div></section>
